#[tokio::test]
async fn actual_http_recipient_128_owner_boundary_publication_and_terminal_ack_transitions() {
    use crate::monad_http::Hash32;
    use crate::monad_mailbox::{MailboxRequestBinding, MailboxResource};
    use crate::store::monad_dm_cbor::Phase;
    use axum::Json;
    use futures::FutureExt;
    for terminal_case in [false, true] {
        let fixture = NativeDirectoryFixture::new().await;
        let mut requests = capacity_requests();
        assert_eq!(requests.len(), 129);
        if terminal_case {
            requests[127] = capacity_prefix_request();
        }
        let mut transactions = Vec::new();
        for (index, request) in requests.iter().enumerate() {
            let members: Vec<_> = request
                .raw_transactions()
                .map(|raw| crate::monad_evm_tx::decode_signed_transaction(raw).unwrap())
                .collect();
            assert_eq!(members[0].nonce, index as u64);
            assert_eq!(
                members[0].sender,
                crate::monad_evm_tx::decode_signed_transaction(
                    requests[0].raw_transactions().next().unwrap()
                )
                .unwrap()
                .sender
            );
            if members.len() == 2 {
                assert_ne!(members[0].sender, members[1].sender);
                assert_eq!(members[1].nonce, 0);
            }
            for (child, transaction) in members.into_iter().enumerate() {
                transactions.push((index, child, transaction));
            }
        }
        let transactions = Arc::new(transactions);
        let final_receipt = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let rpc_receipt = final_receipt.clone();
        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let rpc_calls = calls.clone();
        let rpc = axum::Router::new().route("/",axum::routing::post(move |Json(query):Json<serde_json::Value>| {
            let transactions = transactions.clone(); let final_receipt = rpc_receipt.clone(); let calls = rpc_calls.clone();
            async move {
                calls.fetch_add(1,std::sync::atomic::Ordering::SeqCst);
                let hash = query["params"][0].as_str().unwrap();
                let (index,child,transaction) = transactions.iter().find(|(_,_,tx)| tx.tx_hash.to_hex()==hash).expect("only exact paid members");
                assert!(*index<128,"at-cap new admission must perform no financial RPC");
                let last_unfinished = *index==127 && (*child==1 || !terminal_case);
                let result = match query["method"].as_str().unwrap() {
                    "eth_getTransactionByHash" => serde_json::json!({"hash":hash,"from":transaction.sender.to_hex(),"to":transaction.destination.unwrap().to_hex(),"value":"0x1","input":format!("0x{}",hex::encode(&transaction.input)),"nonce":format!("0x{:x}",transaction.nonce)}),
                    "eth_getTransactionReceipt" if last_unfinished && !final_receipt.load(std::sync::atomic::Ordering::SeqCst) => serde_json::Value::Null,
                    "eth_getTransactionReceipt" => serde_json::json!({"transactionHash":hash,"blockHash":Hash32([1;32]).to_hex(),"blockNumber":format!("0x{:x}",index+1),"transactionIndex":format!("0x{child:x}"),"from":transaction.sender.to_hex(),"to":transaction.destination.unwrap().to_hex(),"gasUsed":"0x5208","status":if terminal_case && *child==1 {"0x0"} else {"0x1"},"logs":[]}),
                    other => panic!("unexpected financial RPC {other}"),
                };
                Json(serde_json::json!({"jsonrpc":"2.0","id":query["id"],"result":result}))
            }
        }));
        let (rpc_url, rpc_stop, rpc_task) = serve_http(rpc).await;
        let runtime_server = server(&fixture, &rpc_url);
        let (url, http_stop, http_task) =
            serve_http(runtime_server.into_router_with_directory(Some(fixture.directory.clone())))
                .await;
        let outcome = std::panic::AssertUnwindSafe(async {
            let client = reqwest::Client::new();
            let put = |request: &ExactRequest| {
                client
                    .put(format!("{url}/message/monad/cbor"))
                    .header("content-type", request.content_type())
                    .body(request.body().to_vec())
            };
            for (index, request) in requests[..127].iter().enumerate() {
                let response = put(request).send().await.unwrap();
                assert_eq!(response.status(), StatusCode::OK, "genuine owner{index}");
                let accepted: serde_json::Value =
                    serde_json::from_slice(&response.bytes().await.unwrap()).unwrap();
                assert_eq!(accepted["phase"], "delivered");
                assert_eq!(
                    accepted["identity"]["submission_identity"],
                    hex::encode(request.submission_identity())
                );
            }
            let response = put(&requests[127]).send().await.unwrap();
            assert_eq!(response.status(), StatusCode::ACCEPTED);
            let accepted: serde_json::Value =
                serde_json::from_slice(&response.bytes().await.unwrap()).unwrap();
            let hash = hash_hex(accepted["identity"]["payload_hash"].as_str().unwrap()).unwrap();
            let recipient =
                Address::from_hex(accepted["identity"]["recipient"].as_str().unwrap()).unwrap();
            let pending = fixture.registry.canonical_dm().get(&hash).unwrap().unwrap();
            assert_eq!(pending.phase, Phase::Pending);
            assert_eq!(
                fixture
                    .registry
                    .canonical_dm()
                    .inbox(recipient, 0, None, 128)
                    .unwrap()
                    .len(),
                127
            );
            let before = calls.load(std::sync::atomic::Ordering::SeqCst);
            assert_eq!(
                put(&requests[128]).send().await.unwrap().status(),
                StatusCode::TOO_MANY_REQUESTS
            );
            assert_eq!(calls.load(std::sync::atomic::Ordering::SeqCst), before);
            assert_eq!(
                put(&requests[0]).send().await.unwrap().status(),
                StatusCode::OK
            );
            assert_eq!(calls.load(std::sync::atomic::Ordering::SeqCst), before);
            final_receipt.store(true, std::sync::atomic::Ordering::SeqCst);
            let response = put(&requests[127]).send().await.unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            let accepted: serde_json::Value =
                serde_json::from_slice(&response.bytes().await.unwrap()).unwrap();
            assert_eq!(
                accepted["phase"],
                if terminal_case { "dead" } else { "delivered" }
            );
            let transitioned = fixture.registry.canonical_dm().get(&hash).unwrap().unwrap();
            assert_eq!(transitioned.reserved_charge, pending.reserved_charge);
            assert_eq!(transitioned.request.body(), requests[127].body());
            if terminal_case {
                let binding = MailboxRequestBinding {
                    resource: MailboxResource::RecoveryAck,
                    recipient,
                    since: 0,
                    cursor: None,
                    limit: 1,
                    max_bytes: 0,
                    recovery_payload_hash: Some(hash),
                    recovery_obligation_id: Some(transitioned.obligation_id),
                };
                let headers = private_headers(
                    &client,
                    &url,
                    fixture.root.path(),
                    &fixture.accounts[1].subject,
                    &binding,
                )
                .await;
                assert_eq!(
                    client
                        .post(format!(
                            "{url}/message/monad/cbor/recovery/{}/{}/{}/ack",
                            recipient.to_hex(),
                            hex::encode(hash),
                            hex::encode(transitioned.obligation_id)
                        ))
                        .headers(headers)
                        .send()
                        .await
                        .unwrap()
                        .status(),
                    StatusCode::OK
                );
                let acknowledged = fixture.registry.canonical_dm().get(&hash).unwrap().unwrap();
                assert!(acknowledged.acknowledged && !acknowledged.reservation);
                assert_eq!(acknowledged.reserved_charge, pending.reserved_charge);
                assert_eq!(
                    fixture
                        .registry
                        .canonical_dm()
                        .inbox(recipient, 0, None, 128)
                        .unwrap()
                        .len(),
                    127
                );
            } else {
                assert!(matches!(transitioned.phase, Phase::Delivered(_)));
                assert_eq!(
                    fixture
                        .registry
                        .canonical_dm()
                        .inbox(recipient, 0, None, 128)
                        .unwrap()
                        .len(),
                    128
                );
            }
            // Every allowed transition consumed its admission-time footprint; release
            // of financial reservation never forgets permanent exact retry ownership.
            assert_eq!(
                fixture
                    .registry
                    .canonical_dm()
                    .financial_usage(recipient)
                    .unwrap()
                    .global_records,
                0
            );
            assert_eq!(
                put(&requests[128]).send().await.unwrap().status(),
                StatusCode::TOO_MANY_REQUESTS
            );
            assert_eq!(
                put(&requests[0]).send().await.unwrap().status(),
                StatusCode::OK
            );
        })
        .catch_unwind()
        .await;
        http_stop.send(()).unwrap();
        http_task.await.unwrap();
        rpc_stop.send(()).unwrap();
        rpc_task.await.unwrap();
        fixture.stop().await;
        if let Err(panic) = outcome {
            std::panic::resume_unwind(panic);
        }
    }
}

